fmt <- function(x) paste(sprintf("%.17g", x), collapse = ", ")
vec <- function(tag, x) cat(sprintf("const %s: [f64; %d] = [%s];\n", tag, length(x), fmt(x)))
# WLS: intercept, slope, their SEs, R²
w <- lm(Y_WLS ~ X_WLS, weights = W_WLS)
vec("WLS", c(coef(summary(w))[, 1], coef(summary(w))[, 2], summary(w)$r.squared))
# Ridge, closed form of ||y - a - Xb||² + λ||b||² (intercept unpenalised)
X <- matrix(X_RIDGE, 50, 3)
Xc <- scale(X, scale = FALSE); yc <- Y_RIDGE - mean(Y_RIDGE)
b <- solve(crossprod(Xc) + 0.5 * diag(3), crossprod(Xc, yc))
vec("RIDGE", c(mean(Y_RIDGE) - sum(colMeans(X) * b), b))
# Elastic net: glmnet(alpha = 0.5, lambda = 0.3, standardize = FALSE)
e <- glmnet(X, Y_RIDGE, alpha = 0.5, lambda = 0.3, standardize = FALSE,
            control = list(thresh = 1e-20, maxit = 1e7))
vec("ENET", c(as.numeric(e$a0), as.numeric(e$beta)))
# Tweedie, log link: intercept, slope, their SEs, deviance
ctl <- glm.control(epsilon = 1e-15, maxit = 200)
tw <- function(tag, y, x, p) {
  f <- glm(y ~ x, family = tweedie(var.power = p, link.power = 0), control = ctl)
  cs <- coef(summary(f)); vec(tag, c(cs[, 1], cs[, 2], deviance(f)))
}
tw("TWEEDIE_GAMMA", Y_TWEEDIE_GAMMA, X_TWEEDIE_GAMMA, 2)
tw("TWEEDIE_POISSON", Y_TWEEDIE_POISSON, X_TWEEDIE_POISSON, 1)
tw("TWEEDIE_INVGAUSS", Y_TWEEDIE_INVGAUSS, X_TWEEDIE_INVGAUSS, 3)
tw("TWEEDIE_CPG", Y_TWEEDIE_CPG, X_TWEEDIE_CPG, 1.5)
